fn check_disconnected(
    n: i8,
    m: i8,
    horizontal: &Vec<char>,
    vertical: &Vec<char>,
) -> bool {
    // Cast to usize to index into the Vec
    let n_usize = n as usize;
    let m_usize = m as usize;

    let first_h = horizontal[0];
    let last_h = horizontal[n_usize - 1];
    let first_v = vertical[0];
    let last_v = vertical[m_usize - 1];

    // Check the four corner conditions
    (first_h == '>' && first_v == 'v')
        || (first_h == '<' && last_v == 'v')
        || (last_h == '>' && first_v == '^')
        || (last_h == '<' && last_v == '^')
}

fn solve(
    n: i8,
    m: i8,
    horizontal: Vec<char>,
    vertical: Vec<char>,
) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

